(() => {
  'use strict';
  const US=globalThis.__CrackGPTUserscript,C=globalThis.CrackGPT,R=globalThis.CrackRanges;
  if(!US||!C||!R)return;
  const SKEY='CG_US_APP_V1',JOB='CG_US_JOB_',RES='CG_US_RESULT_',PROG='CG_US_PROGRESS_',CLAIM='CG_US_CLAIM_',RECV='CG_US_RECEIVER_';
  const load=()=>GM_getValue(SKEY,{presets:[],selectedPresetId:'',cleanerOptions:CrackCleaner.options(),ranges:{},progress:{}});
  const save=v=>GM_setValue(SKEY,v);
  const chatId=()=>{try{return R.crackChatId(location.href)}catch{return null}};
  const uid=()=>crypto.randomUUID();
  const selected=(s)=>s.presets.find(p=>p.id===s.selectedPresetId)||s.presets[0]||null;
  const validatePreset=p=>{if(!p?.name?.trim())throw new Error('프리셋 이름을 입력해 주세요.');if(!p?.prompt?.trim())throw new Error('요약 지침을 입력해 주세요.');return {...p,name:p.name.trim(),chatUrl:C.chatUrl(p.chatUrl)};};
  const rangeKey=(cid,pid)=>`${cid}::${pid}`;

  if(location.origin==='https://crack.wrtn.ai'){
    const host=document.createElement('div');host.id='crack-gpt-summary-host';host.style.cssText='position:fixed;left:18px;bottom:18px;z-index:2147483646;font:13px sans-serif;color:#effff8';
    const root=host.attachShadow({mode:'open'});root.innerHTML=`<style>*{box-sizing:border-box}#p{padding:8px;border:1px solid #37544c;border-radius:16px;background:#111817;box-shadow:0 8px 24px #0008}button{border:0;border-radius:10px;padding:10px 12px;background:#3f7e6d;color:white;font-weight:700;cursor:pointer}button+button{margin-left:6px;background:#263532}#st{max-width:360px;margin-top:7px;white-space:pre-wrap;color:#c9d9d4;font-size:12px}</style><div id="p"><button id="send">GPT 로그 요약</button><button id="set">⚙</button><div id="st"></div></div>`;document.documentElement.append(host);
    const st=root.getElementById('st'),send=root.getElementById('send');
    const stage=k=>{if(C.STAGES[k])st.textContent=C.STAGES[k]};

    function modal(){
      const cid=chatId();if(!cid)return;
      let s=load();if(!s.presets.length){const id=uid();s.presets=[{id,name:'기본 로그 요약',chatUrl:'',prompt:''}];s.selectedPresetId=id;save(s);}let p=selected(s);
      const back=document.createElement('div');back.style.cssText='position:fixed;inset:0;z-index:2147483647;background:#000b;display:grid;place-items:center;padding:16px;font:13px sans-serif;color:#eefcf7';
      back.innerHTML=`<div style="width:min(680px,96vw);max-height:92vh;overflow:auto;background:#111817;border:1px solid #355149;border-radius:20px;padding:20px"><div style="display:flex;justify-content:space-between;align-items:center"><b style="font-size:20px">Crack GPT 로그 요약 설정</b><button id="x">×</button></div><label>프리셋<select id="ps"></select></label><div style="display:flex;gap:8px;margin:8px 0"><button id="new">새 프리셋</button><button id="del">삭제</button></div><label>이름<input id="name"></label><label>ChatGPT 채팅 URL<input id="url" placeholder="https://chatgpt.com/c/..."></label><label>요약 지침<textarea id="prompt"></textarea></label><fieldset><legend>범위</legend><label><input type="radio" name="mode" value="after">마지막 처리 이후</label> <label><input type="radio" name="mode" value="all">전체</label> <label><input type="radio" name="mode" value="manual">직접 지정</label><div><input id="start" type="number" min="1" placeholder="시작 T"><input id="end" type="number" min="1" placeholder="끝 T (비우면 최신)"></div><label><input id="record" type="checkbox"> 이 범위를 마지막 처리 위치로 기록</label></fieldset><fieldset><legend>로그 정리</legend><label><input id="c1" type="checkbox">이미지 마크다운 제거</label><label><input id="c2" type="checkbox">이미지 URL 제거</label><label><input id="c3" type="checkbox">주석 제거</label><label><input id="c4" type="checkbox">빈 줄 정리</label><label><input id="c5" type="checkbox">로어/OOC 제거</label><label><input id="c6" type="checkbox">마크다운 장식 제거</label></fieldset><div id="err" style="color:#ffb7bf;white-space:pre-wrap"></div><div style="text-align:right;margin-top:12px"><button id="save">저장</button></div></div>`;
      const q=x=>back.querySelector(x);const style='display:block;width:100%;margin:6px 0 12px;padding:9px;background:#0a1316;color:white;border:1px solid #355149;border-radius:9px';back.querySelectorAll('input:not([type=radio]):not([type=checkbox]),select,textarea').forEach(e=>e.style.cssText=style);q('#prompt').style.minHeight='190px';
      function render(){s=load();p=selected(s);q('#ps').innerHTML=s.presets.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');q('#ps').value=p.id;q('#name').value=p.name;q('#url').value=p.chatUrl;q('#prompt').value=p.prompt;const c=s.ranges[rangeKey(cid,p.id)]||R.defaults();q(`input[name=mode][value=${c.mode}]`).checked=true;q('#start').value=c.start||1;q('#end').value=c.end||'';q('#record').checked=!!c.record;const o=CrackCleaner.options(s.cleanerOptions);[['#c1','removeImageMarkdown'],['#c2','removeImageUrls'],['#c3','removeComments'],['#c4','normalizeBlankLines'],['#c5','removeLoreOoc'],['#c6','removeMarkdownDecoration']].forEach(([a,k])=>q(a).checked=o[k]);}
      q('#x').onclick=()=>back.remove();q('#ps').onchange=()=>{s.selectedPresetId=q('#ps').value;save(s);render()};q('#new').onclick=()=>{s=load();const id=uid();s.presets.push({id,name:`프리셋 ${s.presets.length+1}`,chatUrl:'',prompt:''});s.selectedPresetId=id;save(s);render()};q('#del').onclick=()=>{s=load();if(s.presets.length<=1)return;s.presets=s.presets.filter(x=>x.id!==q('#ps').value);s.selectedPresetId=s.presets[0].id;save(s);render()};
      q('#save').onclick=()=>{try{s=load();const id=q('#ps').value;const idx=s.presets.findIndex(x=>x.id===id);const np=validatePreset({id,name:q('#name').value,chatUrl:q('#url').value,prompt:q('#prompt').value});s.presets[idx]=np;s.selectedPresetId=id;const mode=q('input[name=mode]:checked')?.value||'after';s.ranges[rangeKey(cid,id)]=R.validateChoice({mode,start:Number(q('#start').value)||1,end:q('#end').value===''?'':Number(q('#end').value),record:q('#record').checked});s.cleanerOptions=CrackCleaner.options({removeImageMarkdown:q('#c1').checked,removeImageUrls:q('#c2').checked,removeComments:q('#c3').checked,normalizeBlankLines:q('#c4').checked,removeLoreOoc:q('#c5').checked,removeMarkdownDecoration:q('#c6').checked});save(s);back.remove();}catch(e){q('#err').textContent=e.message}};document.documentElement.append(back);render();
    }
    root.getElementById('set').onclick=modal;

    send.onclick=async()=>{
      if(send.disabled)return;send.disabled=true;st.textContent='Crack 로그 불러오는 중…';
      try{
        const cid=chatId(),s=load(),p=validatePreset(selected(s));if(!cid)throw new Error('Crack 채팅방에서 실행해 주세요.');const choice=s.ranges[rangeKey(cid,p.id)]||R.defaults();const prev=s.progress[rangeKey(cid,p.id)]||null;
        const structure=await CrackLogExtractor.getCurrentCrackLogStructure(x=>st.textContent=`Crack 로그 불러오는 중… ${x.messageCount}개`);stage('extract');const cut=await R.sliceLogicalTurns(structure,choice,prev);const text=CrackCleaner.cleanRpLog(cut.text,s.cleanerOptions);if(!text.trim())throw new Error('선택 범위의 로그가 없습니다.');
        const id=uid(),url=C.chatUrl(p.chatUrl),hash=await C.digest(text);GM_setValue(JOB+id,{id,url,text,length:text.length,hash,summaryPrompt:p.prompt,fileName:cut.fileName,protocol:C.PROTOCOL,createdAt:Date.now()});stage('connect');GM_openInTab(url,{active:true,insert:true,setParent:true});const deadline=Date.now()+330000;let lastStage='';
        while(Date.now()<deadline){const pg=GM_getValue(PROG+id,null);if(pg?.stage&&pg.stage!==lastStage){lastStage=pg.stage;stage(lastStage)}const r=GM_getValue(RES+id,null);if(r){if(!r.ok)throw new Error(r.error||'전송 실패');if(cut.record){s.progress[rangeKey(cid,p.id)]={...cut.progress,processedAt:Date.now()};save(s);}st.textContent=`ChatGPT로 T${cut.progress.rangeStart} ~ T${cut.progress.rangeEnd} 로그를 전송했습니다.`;GM_deleteValue(JOB+id);GM_deleteValue(RES+id);GM_deleteValue(PROG+id);return;}await C.sleep(400);}throw new Error('전송 결과 확인 시간이 초과되었습니다.');
      }catch(e){st.textContent=`GPT 로그 요약 전송 실패:\n${e.message}`}finally{send.disabled=false}
    };
  }

  if(location.origin==='https://chatgpt.com'){
    const rid=sessionStorage.getItem('CG_US_RID')||uid();sessionStorage.setItem('CG_US_RID',rid);let busy=false;
    const current=()=>{try{return C.chatUrl(location.href)}catch{return null}};
    const visible=e=>e&&e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden';const enabled=e=>visible(e)&&!e.disabled&&e.getAttribute('aria-disabled')!=='true';const read=e=>e instanceof HTMLTextAreaElement?e.value:e.innerText;
    function wait(fn,ms,msg){return new Promise((res,rej)=>{const end=Date.now()+ms;const t=setInterval(()=>{try{const v=fn();if(v){clearInterval(t);res(v)}else if(Date.now()>end){clearInterval(t);rej(new Error(msg))}}catch(e){clearInterval(t);rej(e)}},150)})}
    async function attach(file,form){let input=form.querySelector('input#upload-files[type=file]')||form.querySelector('input[type=file]');if(!input){form.querySelector('button[data-testid="composer-plus-btn"]')?.click();input=await wait(()=>form.querySelector('input[type=file]'),8000,'파일 input을 찾지 못했습니다.')}const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));await C.sleep(900)}
    async function commit(meta){if(current()!==meta.url)throw new Error('ChatGPT 대상 채팅이 변경되었습니다.');const editor=await wait(()=>{const e=document.querySelector('#prompt-textarea');return visible(e)&&e},15000,'ChatGPT 입력창을 찾지 못했습니다.');if(read(editor).trim())throw new Error('ChatGPT 입력창에 작성 중인 내용이 있습니다.');const form=editor.closest('form');if(!form)throw new Error('ChatGPT 입력 폼 구조가 변경되었습니다.');GM_setValue(PROG+meta.id,{stage:'file',ts:Date.now()});await attach(new File([meta.text],meta.fileName,{type:'text/plain;charset=utf-8'}),form);if(C.shouldAttachPrompt(meta.summaryPrompt))await attach(new File([meta.summaryPrompt],C.INSTRUCTION_FILE_NAME,{type:'text/plain;charset=utf-8'}),form);const prompt=C.makePrompt(meta.summaryPrompt);GM_setValue(PROG+meta.id,{stage:'prompt',ts:Date.now()});editor.focus();if(editor instanceof HTMLTextAreaElement){const d=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value');d.set.call(editor,prompt);editor.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:prompt}))}else{document.execCommand('selectAll',false,null);document.execCommand('insertText',false,prompt);editor.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:prompt}))}editor.dispatchEvent(new Event('change',{bubbles:true}));await C.sleep(200);GM_setValue(PROG+meta.id,{stage:'send',ts:Date.now()});const btn=await wait(()=>['button[data-testid="send-button"]','button[data-testid="composer-submit-button"]','button[type="submit"]'].map(x=>form.querySelector(x)).find(enabled),15000,'전송 버튼을 찾지 못했습니다.');btn.click();GM_setValue(PROG+meta.id,{stage:'confirm',ts:Date.now()});await C.sleep(1200);return {ok:true,confirmed:'user-message'};}
    async function poll(){if(busy)return;const url=current();if(!url)return;GM_setValue(RECV+rid,{url,ts:Date.now()});for(const k of GM_listValues().filter(x=>x.startsWith(JOB))){const m=GM_getValue(k,null);if(!m||m.url!==url||GM_getValue(RES+m.id,null))continue;const ck=CLAIM+m.id,old=GM_getValue(ck,null);if(old&&old.rid!==rid&&Date.now()-old.ts<10000)continue;GM_setValue(ck,{rid,ts:Date.now()});await C.sleep(50);if(GM_getValue(ck,null)?.rid!==rid)continue;busy=true;try{if(await C.digest(m.text)!==m.hash)throw new Error('로그 무결성 검증 실패');const r=await commit(m);GM_setValue(RES+m.id,{...r,ts:Date.now()})}catch(e){GM_setValue(RES+m.id,{ok:false,error:e.message||String(e),ts:Date.now()})}finally{busy=false}break;}}
    setInterval(()=>poll().catch(()=>{}),400);
  }
})();
